do $$declare ops uuid:='92000000-0000-0000-0000-000000000001';gid uuid;n bigint;begin
 select id into gid from public.gps_devices where external_id='101';perform set_config('role','service_role',false);
 update public.gps_devices set online_status='offline'where id=gid;update public.gps_device_positions set latitude=33.40,longitude=44.50,fix_time=now()where device_id=gid;perform public.gps_evaluate_operational_alerts();
 select count(*)into n from public.gps_operational_alerts where device_id=gid and resolved_at is null and alert_type in('gps_offline','outside_zone');if n<>2 then raise exception'GPS_OPERATIONAL_ALERT_CREATE_FAIL';end if;
 execute'reset role';perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',ops::text,false);
 select count(*)into n from public.gps_lvn_live_map()where device_id=gid and departure_id is not null and not inside_assigned_zone;if n<>1 then raise exception'GPS_LIVE_MAP_FAIL';end if;select count(*)into n from public.gps_lvn_map_geofences();if n<1 then raise exception'GPS_MAP_ZONES_FAIL';end if;select count(*)into n from public.gps_lvn_open_alerts(100)where device_id=gid;if n<2 then raise exception'GPS_ALERT_RPC_FAIL';end if;
 execute'reset role';perform set_config('role','service_role',false);update public.gps_devices set online_status='online'where id=gid;update public.gps_device_positions set latitude=33.31,longitude=44.36 where device_id=gid;perform public.gps_evaluate_operational_alerts();select count(*)into n from public.gps_operational_alerts where device_id=gid and resolved_at is null and alert_type in('gps_offline','outside_zone');if n<>0 then raise exception'GPS_OPERATIONAL_ALERT_RESOLVE_FAIL';end if;
 raise notice'✅ GPS حي: الخريطة/تنبيه الانقطاع/الخروج من الزون/الإغلاق التلقائي ناجحة';end$$;
